<script setup lang="ts">
import axios from 'axios';

const botStore = useBotStore();

// Controller on port 8084
const CTRL = `${window.location.protocol}//${window.location.hostname}:8084`;

// State
const botStatus = ref<'running' | 'stopped' | 'unknown'>('unknown');
const botMode = ref('');
const botPid = ref<number | null>(null);
const statusMsg = ref('');
const statusOk = ref(true);
const polling = ref<number | null>(null);

// Replay config — restore from localStorage
const saved = JSON.parse(localStorage.getItem('exchangeCtrl') || '{}');
const replayStart = ref(saved.replayStart || '2026-04-01');
const replayEnd = ref(saved.replayEnd || '2026-05-01');
const replaySpeed = ref(saved.replaySpeed ?? 0);

function saveToLocal() {
  localStorage.setItem('exchangeCtrl', JSON.stringify({
    replayStart: replayStart.value,
    replayEnd: replayEnd.value,
    replaySpeed: replaySpeed.value,
    lastMode: botMode.value,
    lastStatus: botStatus.value,
  }));
}

// Replay browser
const replayIndex = ref(0);
const replayTotal = ref(0);
const replayTimestamp = ref('');
const replayCandles = ref<Record<string, Record<string, unknown>>>({});
const replayPlaying = ref(false);
const replayPlayInterval = ref<number | null>(null);

// Exchange data
const exchangeInfo = ref<Record<string, unknown>>({});
const tickers = ref<unknown[]>([]);
const selectedPair = ref('');
const orderBook = ref<{ bids: number[][]; asks: number[][] }>({ bids: [], asks: [] });
const searchFilter = ref('');
const lastRefresh = ref('');

// ── Controller API ──
async function ctrl(path: string, method = 'GET', body?: unknown) {
  const opts: RequestInit = { method };
  if (body) {
    opts.headers = { 'Content-Type': 'application/json' };
    opts.body = JSON.stringify(body);
  }
  const r = await fetch(`${CTRL}${path}`, opts);
  return r.json();
}

async function pollStatus() {
  try {
    const d = await ctrl('/status');
    botStatus.value = d.status;
    botMode.value = d.mode;
    botPid.value = d.pid;
    saveToLocal();
  } catch {
    // Use last known state from localStorage
    botStatus.value = saved.lastStatus || 'unknown';
    botMode.value = saved.lastMode || '';
    botPid.value = null;
  }
}

// ── Actions ──
async function doStop() {
  statusMsg.value = 'Stopping...';
  try {
    await ctrl('/stop', 'POST');
    statusMsg.value = 'Stopped.';
    statusOk.value = true;
    await pollStatus();
  } catch (e) {
    statusMsg.value = `Stop failed: ${e}`;
    statusOk.value = false;
  }
}

async function doStartLive() {
  statusMsg.value = 'Starting Hyperliquid (live)...';
  statusOk.value = true;
  try {
    await ctrl('/start', 'POST', { mode: 'live' });
    statusMsg.value = 'Waiting for bot API...';
    await waitBot();
  } catch (e) {
    statusMsg.value = `Failed: ${e}`;
    statusOk.value = false;
  }
}

async function doStartReplay() {
  statusMsg.value = 'Starting Replay...';
  statusOk.value = true;
  try {
    await ctrl('/restart', 'POST', {
      mode: 'replay',
      replay_config: {
        replay_start: replayStart.value,
        replay_end: replayEnd.value,
        speed: replaySpeed.value,
      },
    });
    statusMsg.value = 'Waiting for bot API...';
    await waitBot();
  } catch (e) {
    statusMsg.value = `Failed: ${e}`;
    statusOk.value = false;
  }
}

async function waitBot() {
  for (let i = 0; i < 30; i++) {
    await new Promise((r) => setTimeout(r, 2000));
    await pollStatus();
    if (botStatus.value !== 'running') {
      statusMsg.value = 'Bot process died. Check logs.';
      statusOk.value = false;
      return;
    }
    try {
      const api = getBotApi();
      await api.get('/ping');
      statusMsg.value = `${botMode.value === 'replay' ? 'Replay' : 'Live'} connected!`;
      statusOk.value = true;
      await loadExchangeData();
      return;
    } catch { /* still starting */ }
  }
  statusMsg.value = 'Bot API timeout. Check logs.';
  statusOk.value = false;
}

// ── Bot API (port 8083) ──
function getBotApi() {
  const loginInfo = useLoginInfo(botStore.selectedBot);
  const api = axios.create({ baseURL: loginInfo.baseUrl.value, timeout: 15000 });
  const token = loginInfo.accessToken.value;
  api.interceptors.request.use((req) => {
    if (token) req.headers.set('Authorization', `Bearer ${token}`);
    return req;
  });
  return api;
}

async function loadExchangeData() {
  try {
    const api = getBotApi();
    const { data } = await api.get('/exchange/info');
    exchangeInfo.value = data;
  } catch { /* replay may not have this */ }
  try {
    const api = getBotApi();
    const { data } = await api.get('/exchange/tickers');
    tickers.value = Object.entries(data.tickers || {})
      .map(([s, t]) => ({ symbol: s, ...(t as Record<string, unknown>) }))
      .sort((a: Record<string, unknown>, b: Record<string, unknown>) =>
        ((b.quoteVolume as number) || 0) - ((a.quoteVolume as number) || 0));
    if (!selectedPair.value && tickers.value.length > 0)
      selectedPair.value = (tickers.value[0] as Record<string, string>).symbol;
    lastRefresh.value = new Date().toLocaleTimeString();
  } catch { /* replay */ }
  if (selectedPair.value) {
    try {
      const api = getBotApi();
      const { data } = await api.get(`/exchange/orderbook/${encodeURIComponent(selectedPair.value)}?limit=10`);
      orderBook.value = data;
    } catch { /* */ }
  }
}

// ── Replay browser ──
async function browseReplay(idx?: number) {
  const i = idx ?? replayIndex.value;
  try {
    const params = new URLSearchParams({
      start: replayStart.value, end: replayEnd.value,
      index: String(i), timeframe: '15m',
    });
    const data = await ctrl(`/browse?${params}`);
    replayIndex.value = data.index;
    replayTotal.value = data.total;
    replayTimestamp.value = data.timestamp;
    replayCandles.value = data.candles || {};
  } catch { /* */ }
}

function replayStep(delta: number) {
  replayIndex.value = Math.max(0, Math.min(replayIndex.value + delta, replayTotal.value - 1));
  browseReplay();
}

function replayTogglePlay() {
  if (replayPlaying.value) {
    if (replayPlayInterval.value) clearInterval(replayPlayInterval.value);
    replayPlayInterval.value = null;
    replayPlaying.value = false;
  } else {
    replayPlaying.value = true;
    replayPlayInterval.value = window.setInterval(() => {
      if (replayIndex.value >= replayTotal.value - 1) {
        replayTogglePlay();
        return;
      }
      replayStep(1);
    }, 500);
  }
}

function replaySliderChange(e: Event) {
  const val = parseInt((e.target as HTMLInputElement).value);
  replayIndex.value = val;
  browseReplay(val);
}

// ── Logs ──
const logLines = ref<string[]>([]);
async function fetchLogs() {
  try {
    const d = await ctrl('/logs');
    logLines.value = d.lines || [];
  } catch { /* */ }
}

// Helpers
function fmtPrice(v: unknown) {
  const n = Number(v);
  if (!n && n !== 0) return '--';
  return n >= 1000 ? n.toLocaleString(undefined, { maximumFractionDigits: 2 }) : n >= 1 ? n.toFixed(4) : n.toFixed(6);
}
function fmtVol(v: unknown) {
  const n = Number(v);
  if (!n) return '--';
  return n >= 1e9 ? `${(n/1e9).toFixed(1)}B` : n >= 1e6 ? `${(n/1e6).toFixed(1)}M` : n >= 1e3 ? `${(n/1e3).toFixed(1)}K` : n.toFixed(0);
}
function pctClass(v: unknown) {
  const n = Number(v);
  return n > 0 ? 'text-green-500' : n < 0 ? 'text-red-500' : 'text-muted-color';
}

const whitelist = computed(() => {
  const wl = (exchangeInfo.value as Record<string, unknown>).whitelist as string[] || [];
  return tickers.value.filter((t) => wl.includes((t as Record<string, string>).symbol));
});
const filtered = computed(() => {
  if (!searchFilter.value) return tickers.value;
  const q = searchFilter.value.toUpperCase();
  return tickers.value.filter((t) => ((t as Record<string, string>).symbol || '').includes(q));
});

function selectPair(p: string) {
  selectedPair.value = p;
  loadExchangeData();
}

// Poll
onMounted(async () => {
  await pollStatus();
  try {
    const d = await ctrl('/replay_config');
    if (d.replay_start) replayStart.value = d.replay_start;
    if (d.replay_end) replayEnd.value = d.replay_end;
    if (d.speed !== undefined) replaySpeed.value = d.speed;
  } catch { /* */ }
  if (botStatus.value === 'running') await loadExchangeData();
  polling.value = window.setInterval(async () => {
    await pollStatus();
    if (botStatus.value === 'running' && botMode.value !== 'replay') {
      await loadExchangeData();
    }
  }, 10000);
});
onUnmounted(() => { if (polling.value) clearInterval(polling.value); });
</script>

<template>
  <div class="flex flex-col gap-3 p-4 h-full overflow-y-auto">

    <!-- ── CONTROL PANEL ── -->
    <div class="rounded-md dark:bg-surface-900 dark:border-surface-700 border p-4">
      <div class="flex items-center gap-3 mb-3">
        <span class="text-xl font-bold" style="color: #64ffda">Exchange Control</span>
        <span
          class="px-3 py-1 rounded-sm text-base font-bold"
          :class="{
            'bg-green-800 text-green-500': botStatus === 'running',
            'bg-slate-800 text-red-500': botStatus === 'stopped',
            'bg-slate-800 text-yellow-500': botStatus === 'unknown',
          }"
        >{{ botStatus === 'running' ? 'RUNNING' : botStatus === 'stopped' ? 'STOPPED' : 'UNKNOWN' }}</span>
        <span v-if="botMode && botMode !== 'stopped'" class="text-base font-bold"
          :style="{ color: botMode === 'replay' ? '#b388ff' : '#4caf50' }">
          {{ botMode === 'replay' ? 'REPLAY' : 'HYPERLIQUID' }}
        </span>
        <span v-if="botPid" class="text-base text-muted-color">PID: {{ botPid }}</span>
        <span class="text-base text-muted-color ms-auto">{{ lastRefresh }}</span>
      </div>

      <!-- Buttons row -->
      <div class="flex gap-3 mb-3">
        <button
          class="px-5 py-2 rounded-md text-base font-bold"
          style="background: #f85149; color: #fff; border: none; cursor: pointer"
          @click="doStop"
        >Stop</button>
        <button
          class="px-5 py-2 rounded-md text-base font-bold"
          style="background: #238636; color: #fff; border: none; cursor: pointer"
          @click="doStartLive"
        >Start Hyperliquid</button>
        <button
          class="px-5 py-2 rounded-md text-base font-bold"
          style="background: #7c4dff; color: #fff; border: none; cursor: pointer"
          @click="doStartReplay"
        >Start Replay</button>
        <button
          class="px-3 py-2 rounded-md text-base"
          style="background: #21262d; color: #8b949e; border: 1px solid #30363d; cursor: pointer"
          @click="fetchLogs"
        >Show Logs</button>
      </div>

      <!-- Replay config -->
      <div class="flex items-center gap-3 p-3 rounded-sm" style="background: #161b22; border: 1px solid #30363d;">
        <span class="text-base font-bold" style="color: #b388ff">Replay Config</span>
        <span class="text-base text-muted-color">Start:</span>
        <input v-model="replayStart" type="date"
          class="text-base px-2 py-1 rounded-sm border dark:border-surface-700 dark:bg-surface-900" />
        <span class="text-base text-muted-color">End:</span>
        <input v-model="replayEnd" type="date"
          class="text-base px-2 py-1 rounded-sm border dark:border-surface-700 dark:bg-surface-900" />
        <span class="text-base text-muted-color">Speed:</span>
        <select v-model.number="replaySpeed"
          class="text-base px-2 py-1 rounded-sm border dark:border-surface-700 dark:bg-surface-900">
          <option :value="0">Max</option>
          <option :value="1">1x</option>
          <option :value="5">5x</option>
          <option :value="10">10x</option>
        </select>
      </div>

      <!-- Status message -->
      <div v-if="statusMsg" class="mt-2 px-3 py-2 rounded-sm text-base font-bold"
        :style="{
          color: statusOk ? '#4caf50' : '#f85149',
          background: statusOk ? '#23863615' : '#f8514915',
          border: '1px solid ' + (statusOk ? '#238636' : '#f85149'),
        }">{{ statusMsg }}</div>
    </div>

    <!-- ── REPLAY BROWSER ── -->
    <div class="rounded-md border p-4" style="border-color: #7c4dff; background: #0d0d1a;">
      <div class="flex items-center gap-3 mb-3">
        <span class="text-lg font-bold" style="color: #b388ff">Data Browser</span>
        <button
          class="px-3 py-1 rounded-md text-base font-bold"
          style="background: #7c4dff; color: #fff; border: none; cursor: pointer"
          @click="browseReplay(0)"
        >Load</button>
        <span class="text-base text-muted-color">{{ replayTotal }} candles</span>
        <span class="text-base text-muted-color ms-auto">Frame {{ replayIndex + 1 }} / {{ replayTotal }}</span>
      </div>

      <!-- Transport controls -->
      <div v-if="replayTotal > 0" class="mb-3">
        <div class="flex justify-between text-base text-muted-color mb-1">
          <span>{{ replayStart }}</span>
          <span class="font-bold text-lg" style="color: #ffd54f">
            {{ replayTimestamp ? new Date(replayTimestamp).toLocaleString() : '--' }}
          </span>
          <span>{{ replayEnd }}</span>
        </div>

        <!-- Slider -->
        <input
          type="range"
          :min="0"
          :max="Math.max(0, replayTotal - 1)"
          :value="replayIndex"
          @input="replaySliderChange"
          style="width: 100%; height: 28px; cursor: pointer; accent-color: #7c4dff;"
        />

        <!-- Buttons -->
        <div class="flex items-center gap-2 mt-2">
          <button class="px-3 py-1 rounded-sm text-lg" style="background:#21262d;color:#8b949e;border:1px solid #30363d;cursor:pointer"
            @click="replayStep(-10)">-10</button>
          <button class="px-3 py-1 rounded-sm text-lg" style="background:#21262d;color:#8b949e;border:1px solid #30363d;cursor:pointer"
            @click="replayStep(-1)">-1</button>
          <button class="px-4 py-1 rounded-sm text-lg font-bold"
            :style="{ background: replayPlaying ? '#f85149' : '#4caf50', color: '#fff', border: 'none', cursor: 'pointer' }"
            @click="replayTogglePlay">{{ replayPlaying ? 'Pause' : 'Play' }}</button>
          <button class="px-3 py-1 rounded-sm text-lg" style="background:#21262d;color:#8b949e;border:1px solid #30363d;cursor:pointer"
            @click="replayStep(1)">+1</button>
          <button class="px-3 py-1 rounded-sm text-lg" style="background:#21262d;color:#8b949e;border:1px solid #30363d;cursor:pointer"
            @click="replayStep(10)">+10</button>
          <button class="px-3 py-1 rounded-sm text-lg" style="background:#21262d;color:#8b949e;border:1px solid #30363d;cursor:pointer"
            @click="browseReplay(0)">Start</button>
          <button class="px-3 py-1 rounded-sm text-lg" style="background:#21262d;color:#8b949e;border:1px solid #30363d;cursor:pointer"
            @click="browseReplay(replayTotal - 1)">End</button>

          <!-- Progress bar -->
          <div class="flex-1 ms-3" style="height: 8px; background: #161b22; border-radius: 4px; overflow: hidden;">
            <div :style="{
              width: (replayTotal > 0 ? (replayIndex / (replayTotal - 1)) * 100 : 0) + '%',
              height: '100%',
              background: 'linear-gradient(90deg, #7c4dff, #b388ff)',
              transition: 'width 0.2s',
            }"></div>
          </div>
          <span class="text-base" style="color: #b388ff">{{ replayTotal > 0 ? ((replayIndex / (replayTotal - 1)) * 100).toFixed(1) : 0 }}%</span>
        </div>
      </div>

      <!-- Candle payload per pair -->
      <div v-if="Object.keys(replayCandles).length" class="grid grid-cols-5 gap-2 mt-2">
        <div v-for="(candle, pair) in replayCandles" :key="pair"
          class="p-3 rounded-sm" style="background: #161b22; border: 1px solid #30363d;">
          <div class="text-base font-bold mb-1" style="color: #64ffda">{{ (pair as string).split('/')[0] }}</div>
          <div style="font-family: monospace; font-size: 14px; line-height: 2;">
            <div class="flex justify-between">
              <span class="text-muted-color">Open</span>
              <span>{{ (candle as Record<string, number>).open }}</span>
            </div>
            <div class="flex justify-between">
              <span class="text-muted-color">High</span>
              <span style="color: #4caf50">{{ (candle as Record<string, number>).high }}</span>
            </div>
            <div class="flex justify-between">
              <span class="text-muted-color">Low</span>
              <span style="color: #f85149">{{ (candle as Record<string, number>).low }}</span>
            </div>
            <div class="flex justify-between">
              <span class="text-muted-color">Close</span>
              <span class="font-bold">{{ (candle as Record<string, number>).close }}</span>
            </div>
            <div class="flex justify-between">
              <span class="text-muted-color">Volume</span>
              <span>{{ (candle as Record<string, number>).volume }}</span>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- ── LOGS ── -->
    <div v-if="logLines.length" class="rounded-md dark:bg-surface-900 dark:border-surface-700 border p-3">
      <h3 class="text-base font-bold mb-2" style="color: #ffd54f">Bot Logs (last 50 lines)</h3>
      <div style="max-height: 250px; overflow-y: auto; font-family: monospace; font-size: 12px; line-height: 1.6; background: #0d1117; border-radius: 4px; padding: 8px;">
        <div v-for="(line, i) in logLines" :key="i"
          :style="{ color: line.includes('ERROR') ? '#f85149' : line.includes('WARNING') ? '#ffd54f' : line.includes('strategy_msg') ? '#64ffda' : '#8b949e' }">
          {{ line }}
        </div>
      </div>
    </div>

    <!-- ── EXCHANGE INFO (only when running) ── -->
    <template v-if="botStatus === 'running'">
      <!-- Capabilities -->
      <div v-if="exchangeInfo.has" class="rounded-md dark:bg-surface-900 dark:border-surface-700 border p-3">
        <h3 class="text-base font-bold mb-2" style="color: #ffd54f">
          {{ (exchangeInfo as Record<string, unknown>).name || 'Exchange' }} — Capabilities
        </h3>
        <div class="flex flex-wrap gap-2">
          <span v-for="(val, key) in ((exchangeInfo as Record<string, unknown>).has as Record<string, boolean> || {})"
            :key="key as string"
            class="px-2 py-1 rounded-sm text-base"
            :class="val ? 'bg-green-800 text-green-500' : 'bg-slate-800 text-muted-color'">
            {{ key }}: {{ val ? 'YES' : 'NO' }}
          </span>
        </div>
      </div>

      <!-- Whitelist tickers -->
      <div v-if="whitelist.length" class="rounded-md dark:bg-surface-900 dark:border-surface-700 border p-3">
        <h3 class="text-base font-bold mb-2" style="color: #64ffda">Whitelist — Live Prices</h3>
        <div class="grid grid-cols-5 gap-2 text-base font-bold text-muted-color mb-1 px-2"
          style="border-bottom: 1px solid #21262d; padding-bottom: 4px;">
          <span>Pair</span><span>Last</span><span>Bid / Ask</span><span>24h %</span><span>Volume</span>
        </div>
        <div v-for="t in whitelist" :key="(t as Record<string, string>).symbol"
          class="grid grid-cols-5 gap-2 text-base px-2 py-1 cursor-pointer rounded-sm"
          :style="{ background: selectedPair === (t as Record<string, string>).symbol ? '#21262d' : '' }"
          @click="selectPair((t as Record<string, string>).symbol)">
          <span class="font-bold" style="color: #64ffda">{{ (t as Record<string, string>).symbol }}</span>
          <span class="font-bold">{{ fmtPrice((t as Record<string, number>).last) }}</span>
          <span>
            <span class="text-green-500">{{ fmtPrice((t as Record<string, number>).bid) }}</span> /
            <span class="text-red-500">{{ fmtPrice((t as Record<string, number>).ask) }}</span>
          </span>
          <span :class="pctClass((t as Record<string, number>).percentage)">
            {{ ((t as Record<string, number>).percentage || 0).toFixed(2) }}%
          </span>
          <span>{{ fmtVol((t as Record<string, number>).quoteVolume) }}</span>
        </div>
      </div>

      <!-- Order Book -->
      <div v-if="orderBook.bids.length" class="grid grid-cols-2 gap-3">
        <div class="rounded-md border p-3" style="border-color: #238636; background: #0a1612">
          <h3 class="text-base font-bold mb-2" style="color: #4caf50">Order Book — {{ selectedPair }}</h3>
          <div style="font-family: monospace;">
            <div v-for="(ask, i) in [...orderBook.asks].reverse()" :key="'a'+i"
              class="grid grid-cols-2 text-base" style="color: #f85149">
              <span>{{ fmtPrice(ask[0]) }}</span><span class="text-end">{{ fmtVol(ask[1]) }}</span>
            </div>
            <div class="my-1 text-center font-bold text-lg" style="color: #ffd54f; border-top: 1px solid #21262d; border-bottom: 1px solid #21262d; padding: 4px;">
              {{ fmtPrice((tickers.find(t => (t as Record<string, string>).symbol === selectedPair) as Record<string, number>)?.last) }}
            </div>
            <div v-for="(bid, i) in orderBook.bids" :key="'b'+i"
              class="grid grid-cols-2 text-base" style="color: #4caf50">
              <span>{{ fmtPrice(bid[0]) }}</span><span class="text-end">{{ fmtVol(bid[1]) }}</span>
            </div>
          </div>
        </div>

        <!-- Ticker detail -->
        <div class="rounded-md border p-3" style="border-color: #7c4dff; background: #0d0d1a">
          <h3 class="text-base font-bold mb-2" style="color: #b388ff">Ticker — {{ selectedPair }}</h3>
          <div v-if="selectedPair" style="font-family: monospace;">
            <div v-for="(val, key) in (tickers.find(t => (t as Record<string, string>).symbol === selectedPair) as Record<string, unknown> || {})"
              :key="key as string"
              class="flex justify-between py-0.5 text-base" style="border-bottom: 1px solid #161b22;">
              <span class="text-muted-color">{{ key }}</span>
              <span>{{ typeof val === 'number' ? fmtPrice(val) : val }}</span>
            </div>
          </div>
        </div>
      </div>

      <!-- All tickers -->
      <div v-if="tickers.length" class="rounded-md dark:bg-surface-900 dark:border-surface-700 border p-3">
        <div class="flex items-center gap-3 mb-2">
          <h3 class="text-base font-bold" style="color: #ffd54f">All Tickers</h3>
          <input v-model="searchFilter" placeholder="Search..."
            class="text-base px-2 py-1 rounded-sm border dark:border-surface-700 dark:bg-surface-900" style="width: 200px;" />
          <span class="text-base text-muted-color ms-auto">{{ filtered.length }} pairs</span>
        </div>
        <div style="max-height: 400px; overflow-y: auto;">
          <div v-for="t in filtered" :key="(t as Record<string, string>).symbol"
            class="grid grid-cols-4 gap-2 text-base px-2 py-0.5 cursor-pointer"
            style="border-bottom: 1px solid #161b22; font-family: monospace;"
            @click="selectPair((t as Record<string, string>).symbol)">
            <span class="font-bold">{{ (t as Record<string, string>).symbol }}</span>
            <span>{{ fmtPrice((t as Record<string, number>).last) }}</span>
            <span :class="pctClass((t as Record<string, number>).percentage)">
              {{ ((t as Record<string, number>).percentage || 0).toFixed(2) }}%
            </span>
            <span>{{ fmtVol((t as Record<string, number>).quoteVolume) }}</span>
          </div>
        </div>
      </div>
    </template>

    <!-- When stopped -->
    <div v-else class="rounded-md dark:bg-surface-900 dark:border-surface-700 border p-4 text-center">
      <span class="text-lg text-muted-color">Bot is {{ botStatus }}. Select a mode and start.</span>
    </div>

  </div>
</template>
